const items = $input.all();
const rows = items.map(i => i.json);

let totalTasks = 0;
let completedTasks = 0;
let blockers = [];
let highlights = [];

for (const row of rows) {
  totalTasks += parseInt(row.tasks_total || 0);
  completedTasks += parseInt(row.tasks_completed || 0);
  if (row.blocker) blockers.push(`- ${row.team_member}: ${row.blocker}`);
  if (row.highlight) highlights.push(`- ${row.team_member}: ${row.highlight}`);
}

const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
const weekOf = new Date().toISOString().split('T')[0];

let report = `:bar_chart: *Weekly Team Report — ${weekOf}*\n\n`;
report += `*Completion Rate:* ${completionRate}% (${completedTasks}/${totalTasks} tasks)\n\n`;

if (highlights.length > 0) {
  report += `:star: *Highlights:*\n${highlights.join('\n')}\n\n`;
}

if (blockers.length > 0) {
  report += `:no_entry_sign: *Blockers:*\n${blockers.join('\n')}\n\n`;
}

report += `_Report generated automatically at ${new Date().toLocaleTimeString()}_`;

return [{json: {report, weekOf, completionRate, totalTasks, completedTasks, blockerCount: blockers.length}}];
